import React, { useState, useEffect } from "react"
import axios from "axios"

const SearchBar = () => {
  const [searchTerm, setSearchTerm] = useState("")
  const [result, setResult] = useState([])

  useEffect(() => {
    // function to fetch data based on the search term
    const fetchSearchResults = async () => {
      try {
        const res = await axios.get(`http://localhost:8800/members?search=${searchTerm}`)
        setResult(res.data)
      } catch (error) {
        console.error("Error fetching search results:", error)
      }
    }

    // call the function when searchTerm changes
    fetchSearchResults()
  }, [searchTerm])

  const handleInputChange = (event) => {
    setSearchTerm(event.target.value)
  }

  const search = (search) => {
    setSearchTerm(search)
    console.log("search ", search)
  }

  return (
    <div className="searchContainer">
      <div className="searchInner">
        <input
          className="searchBar"
          type="text"
          placeholder="Search members..."
          value={searchTerm}
          onChange={handleInputChange}
        />
        <button className="button__search" onClick={search}>
          Search
        </button>
      </div>
      {result.length > 0 && (
        <div className="dropdown">
          {result.map((result) => (
            <div
              key={result.id}
              className="searchItem"
              onClick={() => search(result.firstname)}
            >
              {`${result.firstname} ${result.lastname}`}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

export default SearchBar
